// dispatchLoop is the ASM dispatch entry point; loads ctx into pinned registers and performs the first dispatch (subsequent dispatches happen via DISPATCH_NEXT at each handler tail).
TEXT ·dispatchLoop(SB), NOSPLIT, $0-8
	MOVD ctx+0(FP), R19
	MOVD CTX_CODE_BASE(R19), R22
	MOVD CTX_CODE_LEN(R19), R21
	MOVD CTX_PC(R19), R20
	MOVD CTX_INTS_BASE(R19), R23
	MOVD CTX_FLOATS_BASE(R19), R24
	MOVD CTX_INT_CONSTS_BASE(R19), R26
	MOVD $·flatJumpTable(SB), R25
	DISPATCH_NEXT()

// pathBFallback is the default handler for non-tier-1 opcodes; un-advances pc and returns to Go with EXIT_TIER2.
TEXT ·pathBFallback(SB), NOSPLIT|NOFRAME, $0
	SUB  $1, R20, R20
	MOVD R20, CTX_PC(R19)
	MOVD $EXIT_TIER2, R0
	MOVD R0, CTX_EXIT_REASON(R19)
	MOVD R20, CTX_EXIT_PC(R19)
	RET

// handlerCallExit exits to Go with EXIT_CALL for dedicated isa.SubOpCall handling.
TEXT ·handlerCallExit(SB), NOSPLIT|NOFRAME, $0
	SUB  $1, R20, R20
	MOVD R20, CTX_PC(R19)
	MOVD $EXIT_CALL, R0
	MOVD R0, CTX_EXIT_REASON(R19)
	MOVD R20, CTX_EXIT_PC(R19)
	RET

// handlerReturnExit exits to Go with EXIT_RETURN for dedicated isa.SubOpTier2Return handling.
TEXT ·handlerReturnExit(SB), NOSPLIT|NOFRAME, $0
	SUB  $1, R20, R20
	MOVD R20, CTX_PC(R19)
	MOVD $EXIT_RETURN, R0
	MOVD R0, CTX_EXIT_REASON(R19)
	MOVD R20, CTX_EXIT_PC(R19)
	RET

// handlerReturnVoidExit exits to Go with EXIT_RETURN_VOID for dedicated isa.SubOpTier3ReturnVoid handling.
TEXT ·handlerReturnVoidExit(SB), NOSPLIT|NOFRAME, $0
	SUB  $1, R20, R20
	MOVD R20, CTX_PC(R19)
	MOVD $EXIT_RETURN_VOID, R0
